# New atlas entries from the grain_g2 layer, revision g3 (patches/grain_g2, docs/GRAIN_PORT.md "g3"). E-P7 1.1.
# Same structure as atlas_data.py: E(addr, name, kind, subsystem, conf, sig, notes, source). Merged by gen.py.
# Not repeated: cpu_lock / cpu_unlock 0x6006a922 / 0x6006a96b, psw_mask 0x60054d9f, cache_flush 0x60066fc0, window_map
# 0x60067146, window_mode_get / _set 0x600672ee / 0x600672fe (atlas_data.py).
# v0.32b shipped revision g2: g2_grain 0x607b6430, g2_offs 0x607b678f, g2_row 0x607b67f6, g2_blk 0x607b6834, g2_tile
# 0x607b7420, g2_T 0x607bb420 (releases/v0.32b; docs/GRAIN_PORT.md "g2"). From g3 on those addresses are ring and table bytes.
SRC = 'patches/grain_g2'

E(0x60054dc0, 'psw_restore', 'func', 'rtos', 'V', 'd0 = PSW; retf [],0', 'mov d0,psw + 2 nop: cpu_unlock gives back the PSW that psw_mask returned. Between the two leaves this CPU takes no maskable interrupt (IM = 0 for cpu_lock(0))', SRC)
E(0x601e01e5, 'gc_grain', 'site', 'pipeline', 'V', 'a0 = buffer record, d0 = level 1..3; frame [d2,d3,a2,a3],144', 'Ours (grain_cpu r2): the CPU grain pass, called by gc_ob and reached by jmp from the halation grain hand-off. Since g2 its first 6 B are `jmp g2_grain; nop`; the rest of it, gc_fill 0x601e05c3, gc_next 0x601e060d, gc_p2 0x601e0640, gc_cach 0x601e0669, gc_tbl 0x601e0686, gc_stab 0x601e06ce and gc_G 0x601e074d are unused by the pass (crash_log lives in the body)', SRC)
E(0x607c8430, 'g2_grain', 'func', 'pipeline', 'V', 'a0 = buffer record, d0 = level 1..3; on gc_grain\'s frame, ret [d2,d3,a2,a3],144', 'Ours (grain_g2 g3, code claim 0x607c8420..0x607c9420): r2\'s pass with the ring and the tables in ROM. r2\'s guards (+ 0x33 level), record fields, stage marks, lock / window / flush protocol, slice-edge split; K rows per lock (build constant, 3); no stack beyond r2\'s frame, no malloc / free. The name is g2\'s: other layers know the entry by it', SRC)
E(0x607c8768, 'g3_next', 'func', 'pipeline', 'V', 'calls, shares the frame: r (48,sp), span (76), previous offset (80)', 'Ours: one row\'s offset, gc_next\'s arithmetic: one xorshift32 step, o = ((r >> 8) & 0xffff) * (16383 - Hw) >> 16; (84,sp) = g3_ring + o, (88,sp) = g3_ring + the offset before', SRC)
E(0x607c87a2, 'g3_row', 'func', 'pipeline', 'V', 'calls, shares the frame: pointer (52,sp), pixels (56), ring pointers (84) and (88), T2 (8)', 'Ours: one row or one piece of it. 64 pixels at a time through g2_blk, the rest one by one. Writes only even bytes from the pointer on', SRC)
E(0x607c87b7, 'g2_blk', 'site', 'pipeline', 'V', 'a0 image, a1 ring + o, a2 ring + previous o, d3 groups, a3 T2', 'Ours: the unrolled loop, 518 instructions for 64 px: per pixel s = (k,a1) + (k,a2), Y = (2k,a0), T2[(Y << 6) + s] back to (2k,a0)', SRC)
E(0x607b6420, 'g3_ring', 'data', 'pipeline', 'V', 'u8[16384], values 0..30', 'Ours: the noise ring, r2\'s gc_fill from seed 3201 (verify T runs gc_fill against it). r2 filled it on the heap for every photo', SRC)
E(0x607ba420, 'g3_T', 'data', 'pipeline', 'V', 'u8[3][256][64]: level, Y, s', 'Ours: the Low / Med / High tables T2[Y][s] = T[Y][(s + 1) >> 1], T as r2\'s gc_tbl builds it for 23 / 55 / 91, centre 991; s = sum of two ring bytes, 0..60', SRC)
